<?php
declare(strict_types=1);
require __DIR__.'/shop-common.php';require __DIR__.'/electric-common.php';
try{$db=shop_db();$account=pdg_pricing_account($db,true);if($account===null)shop_answer(401,['error'=>'authentication_required']);shop_customer_cart();if($_SERVER['REQUEST_METHOD']==='GET'){if(empty($_SESSION['electric_request_key'])||isset($_SESSION['electric_submitted'][$_SESSION['electric_request_key']]))$_SESSION['electric_request_key']=bin2hex(random_bytes(24));shop_answer(200,['csrf'=>$_SESSION['csrf'],'request_key'=>$_SESSION['electric_request_key']]);}
 if($_SERVER['REQUEST_METHOD']!=='POST')shop_answer(405,['error'=>'method_not_allowed']);if(!hash_equals($_SESSION['csrf'],(string)($_SERVER['HTTP_X_CSRF_TOKEN']??'')))shop_answer(403,['error'=>'invalid_request']);
 $raw=file_get_contents('php://input',false,null,0,262145);if(strlen($raw)>262144)shop_answer(413,['error'=>'request_too_large']);$input=json_decode($raw,true);if(!is_array($input))shop_answer(422,['error'=>'invalid_input']);
 $key=$input['request_key']??'';if(!is_string($key)||!hash_equals($_SESSION['electric_request_key']??'',$key)||$key==='')shop_answer(409,['error'=>'request_expired']);
 if(isset($_SESSION['electric_submitted'][$key]))shop_answer(200,['ok'=>true,'reference'=>$_SESSION['electric_submitted'][$key]]);
 $name=trim((string)($input['name']??''));$email=trim((string)($input['email']??''));$phone=trim((string)($input['phone']??''));$project=trim((string)($input['project']??''));if($name===''||mb_strlen($name)>160||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>190||mb_strlen($phone)>60||mb_strlen($project)>200)shop_answer(422,['error'=>'invalid_contact']);
 if(time()-(int)($_SESSION['electric_last_request']??0)<10)shop_answer(429,['error'=>'try_later']);
 electric_bootstrap($db);$quote=electric_materials($db,$input,$account['discount_bp']);$drawing=$input['drawing']??null;if(is_array($drawing))$quote['drawing']=$drawing;$ref=bin2hex(random_bytes(12));$q=$db->prepare('INSERT INTO pdg_electric_enquiries(public_ref,customer_name,email,phone,project_name,material_json,materials_cents,missing_prices) VALUES(?,?,?,?,?,?,?,?)');$q->execute([$ref,$name,$email,$phone,$project,json_encode($quote,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$quote['materials_cents'],$quote['missing_prices']]);$_SESSION['electric_submitted'][$key]=$ref;$_SESSION['electric_last_request']=time();shop_answer(201,['ok'=>true,'reference'=>$ref,'quote'=>$quote]);
}catch(InvalidArgumentException $e){shop_answer(422,['error'=>'invalid_materials']);}catch(Throwable $e){shop_answer(503,['error'=>'service_unavailable']);}
